#include <iostream>
#include <string>

int main() {
    std::string text = "The bird was named squawk";

    // Search
    auto pos = text.find("bird");
    if (pos != std::string::npos) {
        std::cout << "Found 'bird' at index: " << pos << "\n";
    }

    // Replace "bird" with "parrot"
    text.replace(pos, 4, "parrot");
    std::cout << "After replace: " << text << "\n";

    // Insert in the middle
    std::size_t mid = text.length() / 2;
    text.insert(mid, "[MID]");
    std::cout << "After insert: " << text << "\n";

    // Erase the inserted tag
    auto tagPos = text.find("[MID]");
    if (tagPos != std::string::npos) {
        text.erase(tagPos, 5);
    }
    std::cout << "After erase: " << text << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <sstream>
#include <cctype>

int main() {
    std::string text = "Antigravity C++17";

    // Backward printing with case inversion (Exercise 21.12 pattern)
    std::cout << "Inverted reverse: ";
    for (auto it = text.rbegin(); it != text.rend(); ++it) {
        char ch = *it;
        if (std::isupper(static_cast<unsigned char>(ch))) {
            std::cout << static_cast<char>(std::tolower(ch));
        } else if (std::islower(static_cast<unsigned char>(ch))) {
            std::cout << static_cast<char>(std::toupper(ch));
        } else {
            std::cout << ch;
        }
    }
    std::cout << "\n";

    // String streams formatting
    std::ostringstream oss;
    oss << "Score: " << 100 << " points, Active: " << std::boolalpha << true;
    std::string formatted = oss.str();
    std::cout << "Stream output: " << formatted << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    // to_string
    int num = 42;
    std::string sNum = std::to_string(num);
    std::cout << "String: " << sNum << "\n";

    // Conversion with base and index tracking
    std::string hexStr = "2A extra text";
    std::size_t unconvertedPos = 0;
    try {
        int val = std::stoi(hexStr, &unconvertedPos, 16);
        std::cout << "Parsed hex 2A -> decimal: " << val << "\n";
        std::cout << "First unconverted char at index: " << unconvertedPos 
                  << " ('" << hexStr[unconvertedPos] << "')\n";
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << "\n";
    }

    // Out of range demonstration
    std::string huge = "99999999999999999999999999";
    try {
        int overflow = std::stoi(huge);
        std::cout << overflow << "\n";
    } catch (const std::out_of_range&) {
        std::cout << "Caught std::out_of_range successfully!\n";
    }

    return 0;
}
